import { MeshStandardNodeMaterial } from 'three/webgpu';
import {
  uv,
  vec2,
  vec3,
  color,
  mix,
  smoothstep,
  sin,
  dot,
  fract,
  texture,
} from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const Group = THREE.Group;

  const colors = config.intent?.visualSpec?.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10',
  };

  const group = new Group();
  group.name = 'features-card-1-label';

  // -------------------------------------------------------------------
  // Engineered gradient label plate (static composition, subtle grain)
  // -------------------------------------------------------------------
  const width = 1.5;
  const height = 0.55;
  const geometry = new THREE.PlaneGeometry(width, height, 1, 1);

  const uvNode = uv();

  // vertical engineered gradient: ink -> surface
  const gradient = mix(
    color(colors.ink),
    color(colors.surface),
    smoothstep(0.0, 1.0, uvNode.y)
  );

  // deterministic fine grain (no time dependence — static composition)
  const grainSeed = dot(uvNode.mul(311.7), vec2(12.9898, 78.233));
  const grainNoise = fract(sin(grainSeed).mul(43758.5453));
  const grain = grainNoise.mul(0.05).sub(0.025);

  let baseColorNode = gradient.add(grain);

  // thin accent edge (<=10% of frame area) — single brightest accent usage
  const accentBar = smoothstep(0.03, 0.0, uvNode.x);
  baseColorNode = mix(baseColorNode, color(colors.accent), accentBar.mul(0.85));

  const material = new MeshStandardNodeMaterial({
    roughness: 0.58,
    metalness: 0.32,
    transparent: true,
  });
  material.colorNode = baseColorNode;

  const plate = new THREE.Mesh(geometry, material);
  plate.name = 'label-plate';
  group.add(plate);

  // -------------------------------------------------------------------
  // Image asset — inset thumbnail blended into the right side of the plate
  // -------------------------------------------------------------------
  let loadedTexture = null;

  function rebuildColorNodeWithTexture(tex) {
    const texColorRaw = texture(tex);
    const texColor = texColorRaw.rgb;
    const texMask = smoothstep(0.5, 0.58, uvNode.x);

    let node = mix(
      color(colors.ink),
      color(colors.surface),
      smoothstep(0.0, 1.0, uvNode.y)
    );
    const g = fract(
      sin(dot(uvNode.mul(311.7), vec2(12.9898, 78.233))).mul(43758.5453)
    )
      .mul(0.05)
      .sub(0.025);
    node = node.add(g);
    node = mix(node, color(colors.accent), accentBar.mul(0.85));
    node = mix(node, texColor, texMask.mul(0.85));

    material.colorNode = node;
    material.needsUpdate = true;
  }

  if (config.imageUrl) {
    ctx.textureLoader
      .loadTexture(config.imageUrl)
      .then((tex) => {
        loadedTexture = tex;
        rebuildColorNodeWithTexture(tex);
      })
      .catch(() => {
        /* silent — gradient-only plate remains valid */
      });
  }

  // -------------------------------------------------------------------
  // Headline text — "Features 1"
  // -------------------------------------------------------------------
  const items =
    config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const headlineItem =
    items.find((i) => i.role === 'headline') ?? items[0] ?? { text: 'Features 1' };

  const headline = ctx.fontAtlas.createText(headlineItem.text ?? 'Features 1', {
    fontSize: headlineItem.typography?.fontSize ?? 39,
    color: colors.paper,
    align: 'left',
    maxWidthPx: 340,
  });
  headline.position.set(-width / 2 + 0.16, -0.02, 0.02);
  group.add(headline);

  // -------------------------------------------------------------------
  // Scene placement (position applied by adapter, keep local transforms)
  // -------------------------------------------------------------------
  group.position.set(-3.2, 1, 0.06);
  group.rotation.set(0, 0, 0);
  group.scale.set(1, 1, 1);

  // -------------------------------------------------------------------
  // Entrance motion — weighted settle, single deliberate transform
  // -------------------------------------------------------------------
  group.scale.set(0.98, 0.98, 0.98);
  const startY = group.position.y - 0.12;
  const targetY = group.position.y;
  group.position.y = startY;

  const tl = gsap.timeline();
  tl.to(group.position, {
    y: targetY,
    duration: 0.7,
    ease: 'power3.out',
  });
  tl.to(
    group.scale,
    {
      x: 1.0,
      y: 1.0,
      z: 1.0,
      duration: 0.9,
      ease: 'power4.out',
    },
    0
  );

  // -------------------------------------------------------------------
  // No cinematic primitives specified for this node.
  // -------------------------------------------------------------------

  group.userData.handlers = {};

  group.userData.cleanup = () => {
    tl.kill();

    geometry.dispose();
    material.dispose();

    if (loadedTexture && typeof loadedTexture.dispose === 'function') {
      loadedTexture.dispose();
    }

    if (headline && typeof headline.userData?.cleanup === 'function') {
      headline.userData.cleanup();
    }
  };

  return group;
}
